1	"use server";
2	
3	/**
4	 * ADMIN-only actions for the free Minecraft product — a separate surface from
5	 * lib/actions-free-minecraft.ts (the customer-facing actions, which all resolve
6	 * "the caller's own server" via `requireUser()` + `userId`). Admins need to
7	 * operate on ANY server by id, so every export here re-checks `requireArea("fleet")`
8	 * itself (never trust the UI alone) and looks the row up by `id`, not by caller.
9	 *
10	 * `"use server"` means every export is a network-reachable endpoint.
11	 */
12	import { revalidatePath } from "next/cache";
13	import { db } from "./db";
14	import { requireArea } from "./rbac";
15	import { withServerSsh, exec, shellQuote } from "./ssh-exec";
16	import { getFreeServerStatus, FREEMC_GAME_TYPES } from "./free-minecraft-control";
17	import { getFreemcHostCapacity, FREEMC_RESERVED_CPUS, FREEMC_RESERVED_RAM_MB } from "./freemc-capacity";
18	import type { SftpServer } from "./sftp";
19	
20	type Result = { ok?: boolean; error?: string };
21	
22	/** Same dedicated Docker host lib/actions-free-minecraft.ts talks to — a real
23	 *  Server row (hostname="freemc-host"), not a customer VPS. */
24	async function freemcHost(): Promise<SftpServer> {
25	  const host = await db.server.findFirst({
26	    where: { hostname: "freemc-host" },
27	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
28	  });
29	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
30	  return host;
31	}
32	
33	/** Lazy, on-demand live status for one server (running + player count) — the
34	 *  list page deliberately does NOT fetch this for every row on load (see
35	 *  app/admin/free-minecraft/page.tsx's header note); this backs a per-row
36	 *  "check status" button instead. */
37	export async function adminGetFreeMinecraftStatus(
38	  id: string
39	): Promise<{ ok: true; running: boolean; players: { online: number; max: number } | null } | { ok: false; error: string }> {
40	  await requireArea("fleet");
41	  const row = await db.freeMinecraftServer.findUnique({ where: { id }, select: { containerName: true } });
42	  if (!row) return { ok: false, error: "Server not found." };
43	
44	  try {
45	    const host = await freemcHost();
46	    const status = await withServerSsh(host, (conn) => getFreeServerStatus(conn, row.containerName));
47	    return { ok: true, running: status.running, players: status.players };
48	  } catch (e) {
49	    console.error("[admin-freemc] status check failed:", e);
50	    return { ok: false, error: "Could not reach the free Minecraft host." };
51	  }
52	}
53	
54	/**
55	 * Force a server's public listing off — a moderation lever for a listing that
56	 * needs to be pulled (abuse report, inappropriate tagline/description, etc.)
57	 * without deleting the server or touching its container.
58	 */
59	export async function adminUnpublishFreeMinecraftServer(id: string): Promise<Result> {
60	  const admin = await requireArea("fleet");
61	  const row = await db.freeMinecraftServer.findUnique({ where: { id }, select: { id: true, isPublic: true } });
62	  if (!row) return { error: "Server not found." };
63	  if (!row.isPublic) return { ok: true };
64	
65	  await db.freeMinecraftServer.update({ where: { id }, data: { isPublic: false } });
66	  await db.auditLog.create({
67	    data: { userId: admin.id, action: "admin.freemc_unpublish", detail: id },
68	  });
69	  revalidatePath("/admin/free-minecraft");
70	  return { ok: true };
71	}
72	
73	/**
74	 * Delete a stray/abandoned free server: `docker rm -f` its container + wipe its
75	 * data dir on freemc-host, then remove the DB row. Same cleanup shape as the
76	 * customer-facing `deleteFreeMinecraftServer` in lib/actions-free-minecraft.ts,
77	 * but admin-gated and looked up by `id` (any server), not by the caller's own
78	 * userId. The DB row is removed even if the SSH cleanup fails — a stuck row
79	 * that no longer resolves to a real container is worse than an orphaned
80	 * container directory an admin can still clean up by hand.
81	 */
82	export async function adminDeleteFreeMinecraftServer(id: string): Promise<Result> {
83	  const admin = await requireArea("fleet");
84	  const row = await db.freeMinecraftServer.findUnique({
85	    where: { id },
86	    select: { id: true, containerName: true, subdomain: true },
87	  });
88	  if (!row) return { error: "Server not found." };
89	
90	  try {
91	    const host = await freemcHost();
92	    await withServerSsh(host, async (conn) => {
93	      await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
94	      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
95	    });
96	  } catch (e) {
97	    console.error("[admin-freemc] delete cleanup failed (row is removed regardless):", e);
98	  }
99	
100	  await db.freeMinecraftServer.delete({ where: { id } });
101	  await db.auditLog.create({
102	    data: { userId: admin.id, action: "admin.freemc_delete", detail: `${id} (${row.subdomain})` },
103	  });
104	  revalidatePath("/admin/free-minecraft");
105	  return { ok: true };
106	}
107	
108	export type FreemcCapacityContainer = {
109	  containerName: string;
110	  cpus: number;
111	  ramMb: number;
112	  /** ISO timestamp, `docker inspect .State.StartedAt` — empty if unavailable. */
113	  startedAt: string;
114	  ownerId: string | null;
115	  ownerName: string | null;
116	  ownerEmail: string | null;
117	  gameType: string;
118	  gameTypeLabel: string;
119	};
120	
121	export type FreemcCapacitySnapshot = {
122	  totalCpus: number;
123	  totalRamMb: number;
124	  committedCpus: number;
125	  committedRamMb: number;
126	  reservedCpus: number;
127	  reservedRamMb: number;
128	  containers: FreemcCapacityContainer[];
129	};
130	
131	/**
132	 * Live host-level capacity snapshot for the admin resource-usage view — see
133	 * lib/freemc-capacity.ts for the accounting (nproc/free -m for host totals,
134	 * `docker inspect` per running mc-free-* container for what's actually
135	 * assigned) and lib/free-minecraft-control.ts's recreateGameTypeContainer /
136	 * lib/actions-free-minecraft.ts's powerAction for where the same helper
137	 * GATES a customer-triggered start. This is read-only — it never starts,
138	 * stops, or otherwise touches a container, just reports what's already true.
139	 *
140	 * Resolves each running container's raw name back to its owning customer +
141	 * active game type via FreeMinecraftServer.containerName, so the admin view
142	 * shows something meaningful instead of a bare `mc-free-<userId>` string. A
143	 * container with no matching DB row (shouldn't normally happen, but SSH/DB
144	 * can disagree transiently) still shows up with null owner fields rather
145	 * than being silently dropped — an admin diagnosing a capacity problem needs
146	 * to see every running container, matched or not.
147	 */
148	export async function adminGetFreemcHostCapacity(): Promise<
149	  { ok: true; snapshot: FreemcCapacitySnapshot } | { ok: false; error: string }
150	> {
151	  await requireArea("fleet");
152	
153	  try {
154	    const host = await freemcHost();
155	    const cap = await withServerSsh(host, (conn) => getFreemcHostCapacity(conn));
156	
157	    const containerNames = cap.runningContainers.map((c) => c.containerName);
158	    const rows = containerNames.length
159	      ? await db.freeMinecraftServer.findMany({
160	          where: { containerName: { in: containerNames } },
161	          select: {
162	            containerName: true,
163	            activeGameType: true,
164	            userId: true,
165	            user: { select: { name: true, email: true } },
166	          },
167	        })
168	      : [];
169	    const byContainer = new Map(rows.map((r) => [r.containerName, r]));
170	
171	    const containers: FreemcCapacityContainer[] = cap.runningContainers.map((c) => {
172	      const row = byContainer.get(c.containerName);
173	      return {
174	        containerName: c.containerName,
175	        cpus: c.cpus,
176	        ramMb: c.ramMb,
177	        startedAt: c.startedAt,
178	        ownerId: row?.userId ?? null,
179	        ownerName: row?.user.name ?? null,
180	        ownerEmail: row?.user.email ?? null,
181	        gameType: row?.activeGameType ?? "unknown",
182	        gameTypeLabel: (row ? FREEMC_GAME_TYPES[row.activeGameType]?.label : undefined) ?? row?.activeGameType ?? "Unknown",
183	      };
184	    });
185	
186	    return {
187	      ok: true,
188	      snapshot: {
189	        totalCpus: cap.totalCpus,
190	        totalRamMb: cap.totalRamMb,
191	        committedCpus: cap.committedCpus,
192	        committedRamMb: cap.committedRamMb,
193	        reservedCpus: FREEMC_RESERVED_CPUS,
194	        reservedRamMb: FREEMC_RESERVED_RAM_MB,
195	        containers,
196	      },
197	    };
198	  } catch (e) {
199	    console.error("[admin-freemc] capacity check failed:", e);
200	    return { ok: false, error: "Could not reach the free Minecraft host." };
201	  }
202	}
