1	"use server";
2	
3	/**
4	 * Free Minecraft servers — one per verified account, running as a Docker
5	 * container on the dedicated "freemc-host" VM behind itzg/mc-router (hostname
6	 * -based routing + auto-scale up/down on connect/idle — see FreeMinecraftServer
7	 * in prisma/schema.prisma for the full architecture note).
8	 *
9	 * KNOWN GAP: disk usage is NOT hard-quota-enforced yet (Docker's storage-opt
10	 * quota needs XFS+pquota, which this host's filesystem doesn't have). The RAM
11	 * cap (Docker --memory, a real hard ceiling) and the total-server-count cap are
12	 * the enforced safety controls for now; `free_minecraft_disk_mb` exists for a
13	 * future periodic `du`-based sweep, not wired to anything yet.
14	 */
15	import { revalidatePath } from "next/cache";
16	import { db } from "./db";
17	import { requireUser } from "./auth";
18	import { assertEmailVerified } from "./email-verification";
19	import { checkRateLimit } from "./rate-limit";
20	import { getSettingBool, getSettingInt, getSetting } from "./settings";
21	import { withServerSsh, exec, shellQuote } from "./ssh-exec";
22	import type { SftpServer } from "./sftp";
23	import { validateRconCommand } from "./game-control";
24	import { schemaFor, validateConfig } from "./game-config";
25	import {
26	  getFreeServerStatus,
27	  getFreeServerPlayers,
28	  sendRcon,
29	  readServerProperties,
30	  writeServerProperties,
31	  liveRconCommandFor,
32	  FREEMC_GAME_TYPES,
33	  FREEMC_GAME_MODES,
34	  legacyPresetKeyFor,
35	  recreateGameTypeContainer,
36	  applyModeProperties,
37	} from "./free-minecraft-control";
38	import { getFreemcHostCapacity, wouldExceedFreemcCapacity } from "./freemc-capacity";
39	import { validateSubdomainFormat, isSubdomainAvailable } from "./game-subdomain";
40	
41	type Result = { error?: string };
42	
43	/**
44	 * Translates one of the OLD flat FREEMC_PRESETS keys (still the only thing
45	 * the not-yet-migrated dashboard UI — components/customer/freemc/*.tsx,
46	 * components/customer/FreeMinecraftPanel.tsx — ever submits) into the new
47	 * two-axis (gameType, gameMode) shape. The 3 old mode-only keys collapse onto
48	 * vanilla+that mode (that's exactly what they always meant); every other key
49	 * is a game type, always paired with survival (the old flat scheme had no
50	 * concept of "preserve the current mode across a preset switch" — every
51	 * preset fully specified its own properties, so this reproduces that
52	 * behavior exactly rather than inventing a new one for legacy callers).
53	 * Returns null for anything unrecognized.
54	 */
55	function mapLegacyPresetKey(key: string): { gameType: string; gameMode: string } | null {
56	  if (key === "creative" || key === "hardcore" || key === "peaceful") return { gameType: "vanilla", gameMode: key };
57	  if (FREEMC_GAME_TYPES[key]) return { gameType: key, gameMode: "survival" };
58	  return null;
59	}
60	
61	/** The dedicated Docker host — a real Server row (Server.hostname="freemc-host"),
62	 *  not a customer VPS. Reused via the same withServerSsh every game/backup
63	 *  action already uses; this just points it at our own internal box instead. */
64	async function freemcHost(): Promise<SftpServer> {
65	  const host = await db.server.findFirst({
66	    where: { hostname: "freemc-host" },
67	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
68	  });
69	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
70	  return host;
71	}
72	
73	export async function getMyFreeMinecraftServer() {
74	  const user = await requireUser();
75	  return db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
76	}
77	
78	export async function createFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
79	  const user = await requireUser();
80	  const subdomain = String(formData.get("subdomain") ?? "");
81	
82	  // Prefer the new two-axis fields (the UI being built in parallel sends
83	  // these); fall back to the legacy flat `preset` field the current create
84	  // form (components/customer/FreeMinecraftPanel.tsx) still submits, so
85	  // account creation keeps working unbroken through the UI migration.
86	  // Defaults to gameType=vanilla, gameMode=survival either way.
87	  const gameTypeField = formData.get("gameType");
88	  const gameModeField = formData.get("gameMode");
89	  let gameType = "vanilla";
90	  let gameMode = "survival";
91	  if (typeof gameTypeField === "string" && FREEMC_GAME_TYPES[gameTypeField]) {
92	    gameType = gameTypeField;
93	    if (typeof gameModeField === "string" && FREEMC_GAME_MODES[gameModeField]) gameMode = gameModeField;
94	  } else {
95	    const mapped = mapLegacyPresetKey(String(formData.get("preset") ?? "vanilla"));
96	    if (mapped) ({ gameType, gameMode } = mapped);
97	  }
98	  const gameTypeDef = FREEMC_GAME_TYPES[gameType];
99	  const gameModeDef = FREEMC_GAME_MODES[gameMode];
100	
101	  if (!(await getSettingBool("free_minecraft_enabled", false))) {
102	    return { error: "Free Minecraft servers aren't open yet — check back soon." };
103	  }
104	
105	  try {
106	    await assertEmailVerified(user);
107	  } catch {
108	    return { error: "Verify your email first — check your inbox for the link." };
109	  }
110	
111	  const rl = checkRateLimit(`freemc:create:${user.id}`, { max: 5, windowMs: 60_000 });
112	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
113	
114	  const sub = subdomain.trim().toLowerCase();
115	  const subdomainError = validateSubdomainFormat(sub);
116	  if (subdomainError) return { error: subdomainError };
117	  if (!(await isSubdomainAvailable(sub))) return { error: "That name is taken — try another." };
118	
119	  const existing = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
120	  if (existing) return { error: "You already have a free server. Delete it before creating another." };
121	
122	  // `free_minecraft_max_concurrent` (lib/actions-settings.ts) is documented as
123	  // "how many free servers may be AWAKE at once" — the host-RAM circuit
124	  // breaker, independent of how many accounts have ever created one. This
125	  // USED to be checked against a row count of every non-DELETED
126	  // FreeMinecraftServer, which counts sleeping (stopped-container) servers
127	  // identically to running ones — the schema's own comment on `status`
128	  // explains why the DB can't tell them apart (mc-router owns awake/asleep
129	  // live, never mirrored back to avoid staleness). Once real accounts filled
130	  // the row-count cap, EVERY new signup was refused as "at capacity" even
131	  // when every existing container was asleep and the host was idle — the
132	  // literal thing this setting exists to prevent (an idle host still
133	  // rejecting signups). Ask the host what's actually awake instead.
134	  const maxTotal = await getSettingInt("free_minecraft_max_concurrent", 8);
135	  try {
136	    const host = await freemcHost();
137	    const capacity = await withServerSsh(host, (conn) => getFreemcHostCapacity(conn));
138	    if (capacity.runningContainers.length >= maxTotal) {
139	      return { error: "Free servers are at capacity right now — please try again later." };
140	    }
141	  } catch (e) {
142	    console.error("[free-minecraft] live capacity check failed, refusing rather than risking overcommit:", e);
143	    return { error: "Couldn't check server capacity right now — please try again in a moment." };
144	  }
145	
146	  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
147	  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
148	
149	  // Derived from userId (unique, known up front) rather than the row's own id,
150	  // so creation is a single write — no awkward "create with a placeholder,
151	  // then patch in the real name" two-phase step that could race.
152	  const containerName = `mc-free-${user.id}`;
153	  let row;
154	  try {
155	    row = await db.freeMinecraftServer.create({
156	      data: {
157	        userId: user.id,
158	        subdomain: sub,
159	        containerName,
160	        status: "CREATING",
161	        activeGameType: gameType,
162	        activeGameMode: gameMode,
163	        preset: legacyPresetKeyFor(gameType, gameMode),
164	      },
165	    });
166	  } catch {
167	    return { error: "That name is taken — try another." };
168	  }
169	
170	  try {
171	    const host = await freemcHost();
172	    const outcome = await withServerSsh(host, async (conn) => {
173	      const setup = await exec(conn, `mkdir -p ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
174	      if (setup.code !== 0) return { ok: false as const, error: setup.stderr || "mkdir failed" };
175	      return recreateGameTypeContainer(conn, {
176	        containerName: row.containerName,
177	        dataPath: `/opt/freemc/servers/${row.id}`,
178	        subdomain: sub,
179	        domain,
180	        ramMb,
181	        ownerId: user.id,
182	        gameType: gameTypeDef,
183	        gameTypeKey: gameType,
184	        gameMode: gameModeDef,
185	      });
186	    });
187	    if (!outcome.ok) throw new Error(outcome.error);
188	  } catch (e) {
189	    // Real, reproduced-live bug this closes: a `waitForServerReady` timeout
190	    // used to delete only the DB row, leaving the actual container running
191	    // (it can finish booting seconds after the app gives up — see
192	    // waitForServerReady's doc comment) — orphaned, invisible to the
193	    // customer, and still occupying a real capacity slot forever since
194	    // nothing with a DB row left ever prompts its removal. Best-effort:
195	    // never let a cleanup failure here mask the real error reported below.
196	    try {
197	      const host = await freemcHost();
198	      await withServerSsh(host, (conn) => exec(conn, `docker rm -f ${shellQuote(containerName)}`, 15_000));
199	    } catch (cleanupErr) {
200	      console.error("[free-minecraft] post-failure container cleanup failed:", cleanupErr);
201	    }
202	    await db.freeMinecraftServer.delete({ where: { id: row.id } }).catch(() => {});
203	    console.error("[free-minecraft] create failed:", e);
204	    // recreateGameTypeContainer's own capacity check (CPU/RAM headroom on the
205	    // host, stricter than the count-based check above) throws an already
206	    // customer-safe, specific message — surface it as-is rather than masking
207	    // it with the generic fallback. A real capacity wall reads very
208	    // differently to a customer than "something broke, try again" — the
209	    // latter reads as a random glitch and, confirmed live, led a customer to
210	    // delete a server that would have created fine moments later once
211	    // whatever else was using the budget finished booting or went idle.
212	    // Any other failure (SSH/docker error, etc.) keeps the generic message —
213	    // those shouldn't leak raw internal error text to the customer.
214	    const msg = e instanceof Error ? e.message : "";
215	    if (msg.includes("at capacity")) return { error: msg };
216	    return { error: "Couldn't start your server — please try again in a moment." };
217	  }
218	
219	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { status: "READY" } });
220	  await db.freeMinecraftWorld.create({
221	    data: { serverId: row.id, gameType, label: gameTypeDef.label, lastPlayedAt: new Date() },
222	  });
223	  revalidatePath("/dashboard/free-minecraft");
224	  return {};
225	}
226	
227	export async function deleteFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
228	  const user = await requireUser();
229	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
230	  if (!row) return { error: "You don't have a free server." };
231	
232	  try {
233	    const host = await freemcHost();
234	    await withServerSsh(host, async (conn) => {
235	      await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
236	      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
237	    });
238	  } catch (e) {
239	    console.error("[free-minecraft] delete cleanup failed (row is removed regardless):", e);
240	  }
241	
242	  await db.freeMinecraftServer.delete({ where: { id: row.id } });
243	  revalidatePath("/dashboard/free-minecraft");
244	  return {};
245	}
246	
247	/** Fetch the caller's server plus its live Docker/RCON status in one round
248	 *  trip. Returns null fields (not an error) when the server is asleep — that's
249	 *  the normal, common state for a free server nobody's playing on right now. */
250	export async function getFreeMinecraftDashboard() {
251	  const user = await requireUser();
252	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
253	  if (!row) return null;
254	
255	  let running = false;
256	  let players: { online: number; max: number } | null = null;
257	  try {
258	    const host = await freemcHost();
259	    const status = await withServerSsh(host, (conn) => getFreeServerStatus(conn, row.containerName));
260	    running = status.running;
261	    players = status.players;
262	  } catch (e) {
263	    console.error("[free-minecraft] status check failed:", e);
264	  }
265	
266	  return { ...row, running, players };
267	}
268	
269	/** Power controls. mc-router already starts/stops on connect/idle
270	 *  automatically — these are the manual overrides (force a restart to apply a
271	 *  settings change now, or stop it to free the slot without waiting it out). */
272	export async function startFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
273	  return powerAction("start");
274	}
275	export async function stopFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
276	  return powerAction("stop");
277	}
278	export async function restartFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
279	  return powerAction("restart");
280	}
281	
282	async function powerAction(action: "start" | "stop" | "restart"): Promise<Result> {
283	  const user = await requireUser();
284	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
285	  if (!row) return { error: "You don't have a free server." };
286	
287	  const rl = checkRateLimit(`freemc:power:${user.id}`, { max: 10, windowMs: 60_000 });
288	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
289	
290	  try {
291	    const host = await freemcHost();
292	    const outcome = await withServerSsh(host, async (conn) => {
293	      // "start" always wakes a currently-stopped container, and "restart" on
294	      // one that's ALREADY stopped does too (docker's restart just starts it)
295	      // — either way that's a customer explicitly turning a container from
296	      // stopped into running, the exact path lib/freemc-capacity.ts's module
297	      // doc says this app controls and should gate (unlike mc-router's own
298	      // passive wake, which happens outside this app entirely). A restart of
299	      // an already-running container doesn't change what's committed, so it's
300	      // deliberately left ungated — same reasoning applies to "stop", which
301	      // only ever frees capacity.
302	      if (action !== "stop") {
303	        const running = await exec(
304	          conn,
305	          `docker inspect -f '{{.State.Running}}' ${shellQuote(row.containerName)}`,
306	          10_000,
307	        );
308	        const isRunning = running.code === 0 && running.stdout.trim() === "true";
309	        if (!isRunning) {
310	          const assigned = await exec(
311	            conn,
312	            `docker inspect ${shellQuote(row.containerName)} --format '{{.HostConfig.NanoCpus}} {{.HostConfig.Memory}}'`,
313	            10_000,
314	          );
315	          if (assigned.code === 0) {
316	            const [nanoCpusRaw, memBytesRaw] = assigned.stdout.trim().split(/\s+/);
317	            const cpus = (Number.parseInt(nanoCpusRaw, 10) || 0) / 1e9;
318	            const ramMb = Math.round((Number.parseInt(memBytesRaw, 10) || 0) / (1024 * 1024));
319	            const capacity = await getFreemcHostCapacity(conn);
320	            const capCheck = wouldExceedFreemcCapacity(capacity, cpus, ramMb);
321	            if (capCheck.exceeds) {
322	              return { ok: false as const, error: "Free servers are at capacity right now — try again in a few minutes." };
323	            }
324	          }
325	          // If the inspect itself failed (container missing entirely), fall
326	          // through and let the docker action below produce the real error —
327	          // no point capacity-gating a container that doesn't exist.
328	        }
329	      }
330	      const r = await exec(conn, `docker ${action} ${shellQuote(row.containerName)}`, 30_000);
331	      if (r.code !== 0) return { ok: false as const, error: r.stderr || `docker ${action} failed` };
332	      return { ok: true as const };
333	    });
334	    if (!outcome.ok) return { error: outcome.error };
335	  } catch (e) {
336	    console.error(`[free-minecraft] ${action} failed:`, e);
337	    return { error: "That didn't work — please try again in a moment." };
338	  }
339	  revalidatePath("/dashboard/free-minecraft");
340	  return {};
341	}
