498	export async function applyFreeMinecraftSettings(_prev: unknown, formData: FormData): Promise<Result> {
499	  const user = await requireUser();
500	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
501	  if (!row) return { error: "You don't have a free server." };
502	
503	  const schema = schemaFor("minecraft");
504	  if (!schema) return { error: "Settings aren't available." };
505	
506	  const raw: Record<string, unknown> = {};
507	  for (const field of schema.fields) {
508	    const v = formData.get(field.key);
509	    if (v === null) continue;
510	    raw[field.key] = field.type === "bool" ? v === "true" : v;
511	  }
512	  const validated = validateConfig("minecraft", raw);
513	  if (!validated.ok) return { error: validated.error };
514	
515	  const properties: Record<string, string> = {};
516	  for (const [k, v] of Object.entries(validated.values)) properties[k] = String(v);
517	
518	  try {
519	    const host = await freemcHost();
520	    await withServerSsh(host, async (conn) => {
521	      // Push live-appliable keys immediately via RCON (instant effect for
522	      // anyone already connected), THEN write server.properties + restart so
523	      // the change also survives the restart and applies to everyone else —
524	      // see liveRconCommandFor's own note on which keys have a real live path.
525	      for (const [k, v] of Object.entries(properties)) {
526	        const liveCmd = liveRconCommandFor(k, v);
527	        if (liveCmd) await sendRcon(conn, row.containerName, user.id, liveCmd).catch(() => {});
528	      }
529	      const write = await writeServerProperties(conn, row.containerName, properties);
530	      if (!write.ok) throw new Error(write.error || "Could not write settings.");
531	      await exec(conn, `docker restart ${shellQuote(row.containerName)}`, 30_000);
532	    });
533	  } catch (e) {
534	    console.error("[free-minecraft] settings apply failed:", e);
535	    return { error: "Couldn't apply settings — please try again." };
536	  }
537	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { preset: "custom" } });
538	  revalidatePath("/dashboard/free-minecraft");
539	  return {};
540	}
